    public function index(): ResponseInterface
    {
        $u=$this->user();if(!$u)return $this->unauthorized();$b=db_connect()->table('labour_workers w')->select('w.*,c.category_code,c.category_name,lc.contractor_code,lc.contractor_name,lc.subcontractor_id,sc.contractor_code AS subcontractor_code,sc.contractor_name AS subcontractor_name,s.status_code,s.status_name')->join('labour_categories c','c.id=w.labour_category_id')->join('labour_contractors lc','lc.id=w.contractor_id AND lc.company_id=w.company_id','left')->join('subcontractors sc','sc.id=lc.subcontractor_id AND sc.company_id=lc.company_id','left')->join('labour_workers_status_masters s','s.id=w.status_id')->where('w.company_id',$this->companyId($u))->where('w.deleted_at',null);
        foreach(['labour_category_id','contractor_id','status_id']as$f)if(ctype_digit((string)($this->request->getGet($f)??'')))$b->where('w.'.$f,(int)$this->request->getGet($f));if(ctype_digit((string)($this->request->getGet('subcontractor_id')??'')))$b->where('lc.subcontractor_id',(int)$this->request->getGet('subcontractor_id'));$q=trim((string)($this->request->getGet('search')??''));if($q!=='')$b->groupStart()->like('w.worker_code',$q)->orLike('w.worker_name',$q)->orLike('w.phone',$q)->orLike('sc.contractor_name',$q)->groupEnd();return $this->ok('Labour workers retrieved successfully.','labour_workers',$b->orderBy('w.id','DESC')->get()->getResultArray());
    }
    public function show(int$id):ResponseInterface{$u=$this->user();if(!$u)return$this->unauthorized();$r=db_connect()->table('labour_workers w')->select('w.*,lc.contractor_code,lc.contractor_name,lc.subcontractor_id,sc.contractor_code AS subcontractor_code,sc.contractor_name AS subcontractor_name')->join('labour_contractors lc','lc.id=w.contractor_id AND lc.company_id=w.company_id','left')->join('subcontractors sc','sc.id=lc.subcontractor_id AND sc.company_id=lc.company_id','left')->where('w.id',$id)->where('w.company_id',$this->companyId($u))->where('w.deleted_at',null)->get()->getRowArray();if(!$r)return$this->notFound();$r['documents']=db_connect()->table('labour_worker_documents')->where('worker_id',$id)->where('deleted_at',null)->get()->getResultArray();return$this->ok('Labour worker retrieved successfully.','labour_worker',$r);}
    public function create():ResponseInterface{return$this->save(null);} public function update(int$id):ResponseInterface{return$this->save($id);}
    public function delete(int$id):ResponseInterface{$u=$this->user();if(!$u)return$this->unauthorized();$r=$this->record('labour_workers',$id,$this->companyId($u),true);if(!$r)return$this->notFound();foreach([['labour_project_assignments','worker_id'],['labour_attendance_entries','worker_id'],['labour_wage_lines','worker_id'],['labour_payments','worker_id']]as[$t,$f])if(db_connect()->table($t)->where($f,$id)->countAllResults())return$this->response->setStatusCode(409)->setJSON(['success'=>false,'message'=>'Worker is in use and cannot be deleted.']);db_connect()->table('labour_workers')->where('id',$id)->update(['deleted_at'=>$this->now(),'updated_by'=>(int)$u->id]);return$this->response->setJSON(['success'=>true,'message'=>'Labour worker deleted successfully.']);}

    public function documents(int$workerId):ResponseInterface{$u=$this->user();if(!$u)return$this->unauthorized();if(!$this->record('labour_workers',$workerId,$this->companyId($u),true))return$this->notFound();return$this->ok('Worker documents retrieved successfully.','worker_documents',db_connect()->table('labour_worker_documents')->where('company_id',$this->companyId($u))->where('worker_id',$workerId)->where('deleted_at',null)->orderBy('id','DESC')->get()->getResultArray());}
