    public function verifyDocument(int$workerId,int$id):ResponseInterface
    { $u=$this->user();if(!$u)return$this->unauthorized();$d=$this->record('labour_worker_documents',$id,$this->companyId($u),true);if(!$d||(int)$d['worker_id']!==$workerId)return$this->notFound();$in=$this->input();$status=(int)($in['verification_status_id']??0);if(!$this->activeMaster('labour_worker_documents_verification_status_masters',$status))return$this->invalid(['verification_status_id'=>'Select a valid active verification status.']);db_connect()->table('labour_worker_documents')->where('id',$id)->update(['verification_status_id'=>$status,'verified_by'=>(int)$u->id,'verified_at'=>$this->now(),'remarks'=>$in['remarks']??$d['remarks'],'updated_at'=>$this->now()]);return$this->ok('Worker document verification updated successfully.','worker_document',$this->record('labour_worker_documents',$id,$this->companyId($u),true)); }
    public function deleteDocument(int$workerId,int$id):ResponseInterface{$u=$this->user();if(!$u)return$this->unauthorized();$d=$this->record('labour_worker_documents',$id,$this->companyId($u),true);if(!$d||(int)$d['worker_id']!==$workerId)return$this->notFound();db_connect()->table('labour_worker_documents')->where('id',$id)->update(['deleted_at'=>$this->now()]);return$this->response->setJSON(['success'=>true,'message'=>'Worker document deleted successfully.']);}

    private function save(?int$id):ResponseInterface
    { $u=$this->user();if(!$u)return$this->unauthorized();$in=$this->input();if($in===null)return$this->invalid(['body'=>'A valid JSON request body is required.']);$company=$this->companyId($u);$old=$id?$this->record('labour_workers',$id,$company,true):null;if($id&&!$old)return$this->notFound();$fields=['labour_category_id','contractor_id','worker_code','worker_name','employment_source_id','gender_id','date_of_birth','phone','emergency_contact_name','emergency_contact_phone','blood_group','address','native_place','id_type_id','id_number_masked','date_joined','date_left','wage_basis_id','base_wage_rate','overtime_rate_per_hour','bank_name','bank_account_name','bank_account_no_masked','bank_ifsc','safety_induction_date','status_id','notes'];$data=array_intersect_key($in,array_flip($fields));$m=array_merge($old??[],$data);$e=$this->required($m,['labour_category_id','worker_code','worker_name','employment_source_id','gender_id','id_type_id','date_joined','wage_basis_id','status_id']);foreach(['labour_category_id'=>['labour_categories',true],'employment_source_id'=>['labour_workers_employment_source_masters',false],'gender_id'=>['labour_workers_gender_masters',false],'id_type_id'=>['labour_workers_id_type_masters',false],'wage_basis_id'=>['labour_workers_wage_basis_masters',false],'status_id'=>['labour_workers_status_masters',false]]as$f=>[$t,$sc]){if($sc){if(!$this->record($t,(int)($m[$f]??0),$company,true))$e[$f]='Select a valid company labour category.';}elseif(!$this->activeMaster($t,(int)($m[$f]??0)))$e[$f]='Select a valid active master value.';}if(!empty($m['contractor_id'])&&!$this->record('labour_contractors',(int)$m['contractor_id'],$company,true))$e['contractor_id']='Select a valid company contractor.';$dup=db_connect()->table('labour_workers')->where('company_id',$company)->where('worker_code',$m['worker_code']??'')->where('deleted_at',null);if($id)$dup->where('id !=',$id);if($dup->countAllResults())$e['worker_code']='Worker code already exists.';if($e)return$this->invalid($e);$data['updated_by']=(int)$u->id;$data['updated_at']=$this->now();if(!$id){$data+=['company_id'=>$company,'created_by'=>(int)$u->id,'created_at'=>$this->now()];}try{$b=db_connect()->table('labour_workers');$id?$b->where('id',$id)->update($data):$b->insert($data);$id??=(int)db_connect()->insertID();return$this->ok($old?'Labour worker updated successfully.':'Labour worker created successfully.','labour_worker',$this->record('labour_workers',$id,$company,true),$old?200:201);}catch(Throwable$x){return$this->serverError('Labour worker save failed.',$x);} }

    private function saveDocument(int$workerId,?int$id):ResponseInterface
    { $u=$this->user();if(!$u)return$this->unauthorized();$company=$this->companyId($u);if(!$this->record('labour_workers',$workerId,$company,true))return$this->notFound();$old=$id?$this->record('labour_worker_documents',$id,$company,true):null;if($id&&(!$old||(int)$old['worker_id']!==$workerId))return$this->notFound();$in=$this->input();if($in===null)return$this->invalid(['body'=>'A valid JSON request body is required.']);$fields=['document_type_id','document_name','document_number','issue_date','expiry_date','file_path','verification_status_id','remarks'];$data=array_intersect_key($in,array_flip($fields));$m=array_merge($old??[],$data);$e=$this->required($m,['document_name','file_path','verification_status_id']);if(!$this->activeMaster('labour_worker_documents_verification_status_masters',(int)($m['verification_status_id']??0)))$e['verification_status_id']='Select a valid verification status.';if($e)return$this->invalid($e);$data['updated_at']=$this->now();if(!$id)$data+=['company_id'=>$company,'worker_id'=>$workerId,'created_by'=>(int)$u->id,'created_at'=>$this->now()];$b=db_connect()->table('labour_worker_documents');$id?$b->where('id',$id)->update($data):$b->insert($data);$id??=(int)db_connect()->insertID();return$this->ok($old?'Worker document updated successfully.':'Worker document created successfully.','worker_document',$this->record('labour_worker_documents',$id,$company,true),$old?200:201); }
